package cl.nexbyte.siger.institucional.notificaciones;
import cl.nexbyte.siger.institucional.nucleo.*;import cl.nexbyte.siger.institucional.robustez.*;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.core.env.Environment;import org.springframework.scheduling.annotation.*;
import java.time.*;import java.nio.file.*;import java.nio.file.attribute.PosixFilePermissions;import java.util.*;import tools.jackson.databind.json.JsonMapper;
@Configuration @EnableScheduling @ConditionalOnProperty(name="institucional.notificaciones.habilitadas",havingValue="true")
public class NotificacionesConfiguration {
 @Bean RecursosNotificacion recursosNotificacion(BaseJdbc db,CatalogoLaboratorio cat,NucleoInstitucional core,HabilitacionNucleo gate){if(!gate.habilitado()||!cat.individual())throw new IllegalStateException("Notificaciones solo con identidad individual de laboratorio");return new RecursosNotificacion(db,cat,core);}
 @Bean TareasPersonales tareasPersonales(BaseJdbc db,RecursosNotificacion permisos,JsonMapper json){return new TareasPersonales(db,permisos,json,Clock.systemUTC());}
 @Bean NotificacionesInstitucionales notificacionesInstitucionales(BaseJdbc db,CatalogoLaboratorio cat,RecursosNotificacion permisos){return new NotificacionesInstitucionales(db,cat,permisos,Clock.systemUTC());}
 @Bean @ConditionalOnProperty(name="institucional.notificaciones.correo.modo",havingValue="GRAPH") TransporteCorreo graphCorreo(Environment e,JsonMapper json){return new GraphMailService(new GraphMailService.Ajustes(e.getRequiredProperty("institucional.notificaciones.graph.tenant"),e.getRequiredProperty("institucional.notificaciones.graph.client"),e.getRequiredProperty("institucional.notificaciones.graph.remitente"),privado(e.getRequiredProperty("institucional.notificaciones.graph.secreto"))),json,Clock.systemUTC());}
 @Bean @ConditionalOnProperty(name="institucional.notificaciones.correo.modo",havingValue="SIMULADO") TransporteCorreo correoSimulado(){return new TransporteCorreo(){public Resultado enviar(Mensaje m){return new Resultado("SIMULADO","SIMULADO",null,0,null);}public boolean real(){return false;}};}
 private static Path privado(String name){try{Path p=Path.of(name).toAbsolutePath().normalize();if(!p.startsWith(Path.of(System.getProperty("user.home"),".local","share","siger"))||!p.equals(p.toRealPath())||Files.isSymbolicLink(p)||!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||!Files.getPosixFilePermissions(p).equals(PosixFilePermissions.fromString("rw-------")))throw new IllegalArgumentException();return p;}catch(Exception failure){throw new IllegalStateException("Custodia privada de correo no válida");}}
 @Bean @ConditionalOnBean(TransporteCorreo.class) CorreosInstitucionales correosInstitucionales(BaseJdbc db,CatalogoLaboratorio cat,NotificacionesInstitucionales notices,TransporteCorreo transport,Environment env){try{var lines=Files.readAllLines(privado(env.getRequiredProperty("institucional.notificaciones.correo.allowlist")));var allowed=new HashSet<String>();for(var line:lines)if(!line.isBlank()){String address=line.strip().toLowerCase(Locale.ROOT);if(!address.matches("[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+"))throw new IllegalArgumentException();allowed.add(address);}return new CorreosInstitucionales(db,cat,notices,transport,allowed,Clock.systemUTC(),env.getRequiredProperty("institucional.notificaciones.correo.campana"));}catch(Exception failure){throw new IllegalStateException("Allowlist/campaña privada no válida");}}
 @Bean MotorNotificaciones motorNotificaciones(TareasPersonales tareas,NotificacionesInstitucionales notices,org.springframework.beans.factory.ObjectProvider<CorreosInstitucionales> correos,Environment env){return new MotorNotificaciones(tareas,notices,correos,env.getProperty("institucional.notificaciones.correo.automatico",Boolean.class,false));}
 public static final class MotorNotificaciones {
  private final TareasPersonales tareas;private final NotificacionesInstitucionales notices;private final org.springframework.beans.factory.ObjectProvider<CorreosInstitucionales> correos;private final boolean automatico;private volatile String estado="PENDIENTE";
  MotorNotificaciones(TareasPersonales t,NotificacionesInstitucionales n,org.springframework.beans.factory.ObjectProvider<CorreosInstitucionales> c,boolean a){tareas=t;notices=n;correos=c;automatico=a;}
  @Scheduled(fixedDelay=15000,initialDelay=15000) public void paso(){try{tareas.temporales();notices.proyectar();var c=correos.getIfAvailable();if(c!=null){c.recuperar();if(automatico)c.automaticos(1);}estado="OPERATIVO";}catch(Exception failure){estado="REINTENTO_INTERNO_PENDIENTE";}}
  public String estado(){return estado;}
 }
}
